style.css:
@-moz-document domain("www.pinterest.com") {
/* Matcha Green and Strawberry Pink (#FFB8CD) Pinterest Theme */

/* Set global text color to matcha green */
  body, html {
    color: #7F9B47 !important;
}

/* Force text color on almost all common elements */
  body, span, a, p, h1, h2, h3, h4, h5, h6, div, li, button, input, textarea, label {
    color: #7F9B47 !important;
}

  /* Force color on SVG icons and paths */
  svg, path {
    fill: #7F9B47 !important;
    stroke: #7F9B47 !important;
}

  /* Search bar text and placeholder in strawberry pink */
  input[type="search"], [placeholder*="Search"] {
    color: #FFB8CD !important;
}
  ::placeholder {
    color: #FFB8CD !important;
    opacity: 1 !important;
}

  /* Scrollbar styling */
  *::-webkit-scrollbar {
    width: 12px !important;
    background: #DCDFC4 !important;
}

  *::-webkit-scrollbar-thumb {
    background-color: #7F9B47 !important;
    border-radius: 6px !important;
    border: 3px solid #DCDFC4 !important;
}

  /* Save button styling */
  .d24 {
    background-color: #bfd786 !important;
    color: #7F9B47 !important;
    border: 1px solid #7F9B47 !important;
    box-shadow: none !important;
}

  /* Text color inside Save button */
  .d24 span, .d24 div {
    color: #7F9B47 !important;
}

  /* Hover effect on Save button */
  .d24:hover {
    background-color: #FFB8CD !important;
    color: white !important;
   border-color: #FFB8CD !important;
}

  /* Hover effect on links and buttons */
  a:hover, button:hover {
    color: #FFB8CD !important;
}

  /* Pinterest logo in strawberry pink */
  [aria-label="Pinterest"] svg,
  [data-test-id="headerPinterestLogo"] svg,
  svg[viewBox="0 0 24 24"][aria-hidden="true"] path[d*="M12"] {
    fill: #FFB8CD !important;
    stroke: #FFB8CD !important;
}

  /* Comments section (comment text and usernames) in strawberry pink */
  [data-test-id="comment"], 
  [data-test-id="comment"] span, 
  [data-test-id="comment"] div, 
  [data-test-id="comment"] p {
    color: #FFB8CD !important;
}

  /* Matcha green text styles */
  .zI7:nth-child(4) > .XiG .Uvi {
    color: #7F9B47 !important;
}

  .zI7:nth-child(5) .Uvi {
    color: #7F9B47 !important;
}

  .Hn_ {
    color: #7F9B47 !important;
}

  /* Strawberry pink comment section styles */
  #comments-heading {
    color: #FFB8CD !important;
}

  .public-DraftStyleDefault-block {
    color: #FFB8CD !important;
}

  .g_1 {
