}

  .zI7:nth-child(2) > .XiG .nrl .Uvi {
    color: #FFB8CD !important;
  }

  .XiG > .XiG .nrl .Uvi {
    color: #FFB8CD !important;
  }

  .zI7:nth-child(2) > .yfm .Uvi {
    color: #FFB8CD !important;
  }

  .S9z > .yfm .Uvi {
    color: #FFB8CD !important;
  }

  .H-G > .XiG .Uvi {
    color: #FFB8CD !important;
  }

  .xuA:nth-child(2) > .KS5 .Uvi {
